// How notifications look. Anything can post one with notify({ title, body,
// level, icon, action }); replace this mod to restyle them all. Click to
// run its action (e.g. go to the agent) and dismiss it.

import { View, div, image } from "gpui-kit";
import { v_flex, h_flex } from "gpui-base";
import { props, closeOverlay, openOverlay, run, theme } from "herdr";
// <flat-tokens> generated by lib/herdr_flat/sync from lib/herdr_flat/flat.js; edit there
const R = 1;
const LINE = 1;
const UNIT = 5;
const S1 = UNIT;
const S2 = UNIT * 2;
const S3 = UNIT * 3;
const S4 = UNIT * 4;
const HAIR = 2;
const TEXT = 13;
const SMALL = 11;
const H3 = 15;
const H2 = 18;
const H1 = 22;
// </flat-tokens>

const DOT = { error: "blocked", warning: "working", success: "done", info: "accent" };

// Herdr wraps its toasts in its own frame (rounded corners, a shadow), even
// with "frame": "none" in mod.json. So the toast Herdr opens hands its props
// to an unframed window of this same mod in the bottom-right corner and closes
// at once; that window closes itself after the timeout.
const TIMEOUT = 6000;
const WIDTH = 360;
const HEIGHT = 64;
const STATUS = 28; // the flat layout's status bar (layouts/flat.json)
// A window's `at` is its top left and is not clamped, so place it from the
// viewport: bottom right, above the status bar.
function corner() {
  const v = window.viewport_size();
  return { x: Math.max(0, v.width - WIDTH - S4), y: Math.max(0, v.height - HEIGHT - STATUS - S4) };
}
const WINDOW = { kind: "window", frame: "none", width: WIDTH, height: HEIGHT };

export default class Toast extends View {
  init(_props, cx) {
    const p = props() ?? {};
    if (!p.flat && p.overlay) {
      const { overlay, ...note } = p;
      closeOverlay(overlay);
      openOverlay({ ...WINDOW, at: corner(), mod: "flat-toast", props: { ...note, flat: true } });
      return;
    }
    if (!p.flat) return;
    cx.timer.after(p.timeout ?? TIMEOUT, () => {
      const overlay = props()?.overlay;
      if (overlay) closeOverlay(overlay);
    });
  }

  render(cx) {
    const t = theme();
    const p = props() ?? {};
    if (!p.flat) return div();
    const login = /^([a-z0-9][a-z0-9_.-]{0,31}) needs login; run hc machine login \1$/.exec(p.body ?? "");
    const command = login ? `hc machine login ${login[1]}` : null;
    return h_flex()
      .id("toast")
      .size_full()
      .px(S4)
      .gap(S2)
      .items_center()
      .bg(t.popover).border(LINE).border_color(t.border).rounded(R)
      .cursor_pointer()
      .hover((s) => s.bg(t.hover))
      .on_click(() => {
        if (p.action?.name) run(p.action.name, p.action.args ?? {});
        if (p.overlay) closeOverlay(p.overlay);
      })
      .child(p.icon ? image(p.icon).w(18).h(18).flex_none() : div().size(8).rounded_full().flex_none().bg(t[DOT[p.level] ?? "accent"]))
      .child(
        v_flex()
          .flex_1()
          .overflow_hidden()
          .child(div().truncate().font_semibold().text_size(TEXT).text_color(t.foreground).child(login ? `${login[1]} needs a login: run` : p.title ?? ""))
          .when(!login && Boolean(p.body), (el) => el.child(div().truncate().text_size(TEXT).text_color(t.muted).child(p.body ?? "")))
          .when(Boolean(login), (el) => el.child(h_flex().gap(S2).items_center()
            .child(div().flex_1().min_w(0).truncate().tooltip(command).text_size(TEXT).text_color(t.muted).child(command))
            .child(div().id("toast-login-copy").flex_none().px(S1).py(S1).rounded(R).bg(t.raised)
              .text_size(TEXT).text_color(t.foreground).cursor_pointer().hover(s => s.bg(t.hover))
              .on_click((_e, cx) => { cx.stop_propagation(); cx.write_to_clipboard(command); this.copied = true; cx.notify(); })
              .child(this.copied ? "Copied" : "Copy")))),
      );
  }
}
